// Pages that changed since the last run, with the screenshot and a diff image.
return $input.all().filter(i => i.json.changed === true).map(i => ({ json: {
  url: i.json.url, device: i.json.device, diffPercent: i.json.diffPercent, screenshot: i.json.imageUrl, diff: i.json.diffImageUrl } }));
